// Sprint 5 — AI Core now owns provider selection, prompt versioning, and
// retries (AiRoutingPolicy), so this node no longer resolves any of that;
// it just carries the lead through to the Call AI Core step.
const lead = $json.lead || {};
const workflowExecutionId = $json.workflowExecutionId;

return [{
  json: {
    lead,
    workflowExecutionId,
    startedAt: Date.now(),
  },
}];

// Sprint 5 — replaces the old Select Provider / Load Prompt Template /
// Build Initial Prompt / Prepare Attempt / Call Ollama / Classify Ollama
// Result / Outcome Router / Check Retry Budget / Prepare Retry chain.
// AI Core (AiRoutingService) already resolved the Brain, prompt version,
// provider/model, ran its own retries, and computed the HIGH/MEDIUM/LOW
// confidence tier -- this node's only job is mapping that result onto the
// CRM's qualification write-back contract. Same 'never strand a lead'
// guarantee as before: every outcome, including a failed AI Core call,
// still produces a payload for Submit Qualification.
const config = $('Load Config').item.json;
const lead = config.lead;
const response = $json;

const base = {
  contractVersion: '1',
  workflowExecutionId: config.workflowExecutionId,
  workflowName: '03-ai-qualification',
  leadId: lead.id,
  durationMs: Date.now() - config.startedAt,
};

function manualReviewPayload(reason, errorMessage, provider, model, promptVersion) {
  return {
    ...base,
    provider: provider || 'unknown',
    model: model || 'unknown',
    promptVersion: promptVersion || 'unknown',
    leadScore: 0,
    confidence: 0,
    priority: 'MEDIUM',
    painPoints: [],
    recommendedAction: 'Manual review required -- automated AI qualification did not complete successfully.',
    summary: `AI qualification failed for ${lead.contactName}.`,
    reasoning: reason || 'Unknown failure.',
    needsManualReview: true,
    errorMessage,
  };
}

if (response && response.error) {
  const message = String((response.error && response.error.message) || response.error || 'AI Core call failed.');
  return [{ json: manualReviewPayload(message, `[request_failed] ${message}`) }];
}

const result = response && response.data;

if (!result || result.outcome !== 'VALID' || !result.outputJson) {
  const outcome = (result && result.outcome) || 'UNKNOWN';
  return [{
    json: manualReviewPayload(
      `AI Core returned outcome=${outcome}.`,
      `[${outcome}] AI Core did not return a usable result.`,
      result && result.provider,
      result && result.model,
      result && result.promptVersion
    ),
  }];
}

const parsed = result.outputJson;
const budget = parsed.budgetEstimate || null;
const tier = result.confidence; // AI Core's own HIGH/MEDIUM/LOW tier
const annotation = tier === 'MEDIUM' ? ' [AI-assisted, review recommended]' : '';

return [{
  json: {
    ...base,
    provider: result.provider,
    model: result.model,
    promptVersion: result.promptVersion,
    leadScore: Math.round(parsed.leadScore),
    confidence: parsed.confidence,
    confidenceTier: tier || undefined,
    priority: parsed.priority,
    industry: parsed.industry || undefined,
    companySizeEstimate: parsed.companySizeEstimate || undefined,
    budgetEstimateMin: budget ? budget.min : undefined,
    budgetEstimateMax: budget ? budget.max : undefined,
    budgetEstimateCurrency: budget ? budget.currency : undefined,
    buyingIntent: parsed.buyingIntent || undefined,
    urgency: parsed.urgency || undefined,
    decisionMakerIdentified: parsed.decisionMakerIdentified,
    estimatedTimeline: parsed.estimatedTimeline || undefined,
    riskLevel: parsed.riskLevel || undefined,
    painPoints: parsed.painPoints || [],
    recommendedAction: `${parsed.recommendedAction}${annotation}`,
    summary: parsed.summary,
    reasoning: parsed.reasoning,
    needsManualReview: result.needsManualReview,
  },
}];
